<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { message } from 'ant-design-vue'
import api from '@/api/client'
import PageBackButton from '@/components/PageBackButton.vue'
const jobs=ref<any[]>([]); const applications=ref<any[]>([]); const loading=ref(false); const drawer=ref(false); const selectedJob=ref<any>(null)
const form=reactive({name:'',email:'',phone:'',school:'',major:'',graduation_year:2027,resume_text:'',cover_note:''})
async function load(){loading.value=true;try{jobs.value=(await api.get('/api/v1/recruitment/jobs?status=开放')).data.data;applications.value=(await api.get('/api/v1/recruitment/applications')).data.data}catch(error:any){message.error(error.response?.data?.detail || '岗位加载失败')}finally{loading.value=false}}
function apply(job:any){selectedJob.value=job;Object.assign(form,{name:'',email:'',phone:'',school:'',major:'',graduation_year:2027,resume_text:'',cover_note:''});drawer.value=true}
async function submit(){if(!selectedJob.value)return;try{await api.post('/api/v1/recruitment/applications',{...form,job_id:selectedJob.value.id});message.success('投递成功');drawer.value=false;await load()}catch(error:any){message.error(error.response?.data?.detail || '投递失败')}}
onMounted(load)
</script>
<template><div class="page-frame business-page"><header class="page-heading"><div><p class="eyebrow">C-SIDE APPLICATION</p><h1>学生投递端</h1><p>只展示开放岗位。投递记录来自真实数据库。</p></div><PageBackButton fallback="/modules/resume-screening"/></header><a-spin :spinning="loading"><section class="business-grid two-columns"><a-card class="plain-panel" :bordered="false"><div class="section-title"><h2>开放岗位</h2></div><a-empty v-if="!jobs.length" description="暂无开放岗位"/><a-list v-else item-layout="vertical" :data-source="jobs"><template #renderItem="{item}"><a-list-item><template #actions><a-button type="primary" @click="apply(item)">查看详情并投递</a-button></template><a-list-item-meta :title="item.title" :description="`${item.department} · ${item.location} · ${item.employment_type}`"/><p>{{item.description}}</p><p><strong>岗位要求：</strong>{{item.requirements}}</p></a-list-item></template></a-list></a-card><a-card class="plain-panel" :bordered="false"><h2>我的投递记录</h2><a-empty v-if="!applications.length" description="还没有投递记录"/><a-list v-else :data-source="applications"><template #renderItem="{item}"><a-list-item><a-list-item-meta :title="item.job_title" :description="`${item.name} · ${item.email}`"/><a-tag>{{item.status}}</a-tag></a-list-item></template></a-list></a-card></section></a-spin><a-drawer v-model:open="drawer" title="提交岗位申请" width="560"><a-form layout="vertical"><a-form-item label="姓名" required><a-input v-model:value="form.name" aria-label="姓名"/></a-form-item><a-form-item label="邮箱" required><a-input v-model:value="form.email" aria-label="邮箱"/></a-form-item><a-form-item label="手机号"><a-input v-model:value="form.phone"/></a-form-item><a-form-item label="学校"><a-input v-model:value="form.school"/></a-form-item><a-form-item label="专业"><a-input v-model:value="form.major"/></a-form-item><a-form-item label="毕业年份"><a-input-number v-model:value="form.graduation_year" :min="2000" :max="2100" style="width:100%"/></a-form-item><a-form-item label="简历内容"><a-textarea v-model:value="form.resume_text" aria-label="简历内容" :rows="7" placeholder="填写教育、实习、项目和技能信息"/></a-form-item><a-form-item label="求职说明"><a-textarea v-model:value="form.cover_note" aria-label="求职说明" :rows="3"/></a-form-item><a-button type="primary" block @click="submit">提交投递</a-button></a-form></a-drawer></div></template>
